text = path.read_text()
old = '<Link href={`/organizer/events/new?edit=${event.id}`} className="grid h-8 w-8 place-items-center rounded-full bg-black/[.04] dark:bg-white/[.06]"><Pencil size={14} /></Link>'
new = '<Link href={`/organizer/events/new?edit=${event.id}`} className="grid h-8 w-8 place-items-center rounded-full bg-black/[.04] dark:bg-white/[.06]"><Pencil size={14} /></Link><button onClick={() => setStatus.mutate({ eventId: event.id, status: "archived" })} className="grid h-8 w-8 place-items-center rounded-full bg-black/[.04] text-[#77777f] hover:text-red-500 dark:bg-white/[.06]"><Trash2 size={14} /></button>'
if old not in text:
    raise SystemExit('organizer action anchor not found')
