replacement = r'''function CreateEventPage() { const auth = useAuth({ redirectOnUnauthenticated: false }); const [, navigate] = useLocation(); const params = new URLSearchParams(window.location.search); const editingId = Number(params.get("edit")) || undefined; const mine = trpc.events.mine.useQuery(undefined, { enabled: Boolean(auth.user) && ["organizer", "admin"].includes(auth.user?.role ?? ""), retry: false }); const create = trpc.events.create.useMutation(); const update = trpc.events.update.useMutation(); const editing = mine.data?.find(event => event.id === editingId); const [title, setTitle] = useState(""); const [slug, setSlug] = useState(""); const [category, setCategory] = useState(categories[0]); const [description, setDescription] = useState(""); const [venue, setVenue] = useState(""); const [location, setEventLocation] = useState(""); const [startsAt, setStartsAt] = useState(""); const [endsAt, setEndsAt] = useState(""); const [imageUrl, setImageUrl] = useState(""); const [upi, setUpi] = useState(""); const [whatsapp, setWhatsapp] = useState(""); const [ticketName, setTicketName] = useState("General admission"); const [price, setPrice] = useState("0"); const [quantity, setQuantity] = useState("100"); useEffect(() => { if (!editing) return; setTitle(editing.title); setSlug(editing.slug); setCategory(editing.category); setDescription(editing.description); setVenue(editing.venue); setEventLocation(editing.location); setStartsAt(formatDateTimeLocal(editing.startsAt)); setEndsAt(formatDateTimeLocal(editing.endsAt)); setImageUrl(editing.imageUrl ?? ""); setUpi(editing.paymentUpi ?? ""); setWhatsapp(editing.paymentWhatsapp ?? ""); setTicketName(editing.tickets[0]?.name ?? "General admission"); setPrice(String(Math.round((editing.tickets[0]?.priceMinor ?? 0) / 100))); setQuantity(String(editing.tickets[0]?.quantity ?? 100)); }, [editing?.id]); useEffect(() => { if (title && !slug && !editing) setSlug(title.toLowerCase().trim().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "")); }, [title, slug, editing]); if (auth.loading || (editingId && mine.isLoading)) return <LoadingState />; if (!auth.user) return <AuthRequired title="Create an event" />; if (!["organizer", "admin"].includes(auth.user.role)) return <ErrorState title="Organizer access required" body="Ask an administrator to assign the organizer role to your account." />; const submit = async (e: React.FormEvent) => { e.preventDefault(); if (!title || !slug || !description || !venue || !location || !startsAt || !endsAt) { toast.error("Complete all required event details."); return; } const data = { title, slug, category, description, venue, location, startsAt: new Date(startsAt), endsAt: new Date(endsAt), imageUrl: imageUrl || null, paymentUpi: upi || null, paymentWhatsapp: whatsapp || null, tickets: [{ name: ticketName, description: "Entry to the event", priceMinor: Math.round(Number(price || 0) * 100), quantity: Number(quantity) }] }; try { if (editingId) await update.mutateAsync({ eventId: editingId, data }); else await create.mutateAsync(data); toast.success(editingId ? "Event updated" : "Event saved as draft"); navigate("/organizer"); } catch (error: any) { toast.error(error?.message ?? "Unable to save event"); } }; const saving = create.isPending || update.isPending; return <><AppHeader /><main className="container max-w-[960px] py-10 md:py-16"><Link href="/organizer" className="inline-flex items-center gap-2 text-[12px] font-bold text-[#85858d]"><ArrowLeft size={14} /> Back to organizer</Link><h1 className="mt-8 text-[52px] font-black leading-none tracking-[-.08em]">{editingId ? "Make it even" : "What are you"}<br /><span className="text-[#7166e8]">{editingId ? "better." : "creating?"}</span></h1><p className="mt-5 max-w-[520px] text-[14px] leading-6 text-[#85858d]">{editingId ? "Update the database record, then publish changes from your organizer workspace." : "Save a real draft to the database, then publish it when the details are ready."}</p><form onSubmit={submit} className="mt-10 grid gap-8 lg:grid-cols-[1fr_330px]"><div className="space-y-7"><Panel title="Essentials"><div className="grid gap-4 sm:grid-cols-2"><Field label="Event name" placeholder="Sunset Sessions" value={title} onChange={setTitle} /><Field label="URL slug" placeholder="sunset-sessions" value={slug} onChange={setSlug} /><label className="block sm:col-span-2"><span className="text-[11px] font-black text-[#73737b]">Category</span><select value={category} onChange={e => setCategory(e.target.value)} className="mt-2 h-11 w-full rounded-[10px] border border-black/10 bg-white px-3 text-[13px] font-semibold dark:border-white/10 dark:bg-[#1c1c21]">{categories.map(item => <option key={item}>{item}</option>)}</select></label></div></Panel><Panel title="When & where"><div className="grid gap-4 sm:grid-cols-2"><Field label="Starts" type="datetime-local" placeholder="" value={startsAt} onChange={setStartsAt} /><Field label="Ends" type="datetime-local" placeholder="" value={endsAt} onChange={setEndsAt} /><Field label="Venue" placeholder="The Quorum" value={venue} onChange={setVenue} /><Field label="City & state" placeholder="Mumbai, Maharashtra" value={location} onChange={setEventLocation} /></div></Panel><Panel title="Story"><label className="block"><span className="text-[11px] font-black text-[#73737b]">Description</span><textarea value={description} onChange={e => setDescription(e.target.value)} rows={6} className="mt-2 w-full resize-none rounded-[12px] border border-black/10 bg-white p-3 text-[13px] font-semibold outline-none dark:border-white/10 dark:bg-[#1c1c21]" placeholder="What will people experience?" /></label><div className="mt-4"><Field label="Image URL (optional)" placeholder="https://..." value={imageUrl} onChange={setImageUrl} /></div></Panel></div><aside className="h-fit space-y-5"><Panel title="Ticket type"><Field label="Name" placeholder="General admission" value={ticketName} onChange={setTicketName} /><div className="mt-4 grid gap-4 sm:grid-cols-2"><Field label="Price (₹)" placeholder="999" value={price} onChange={setPrice} type="number" /><Field label="Quantity" placeholder="100" value={quantity} onChange={setQuantity} type="number" /></div></Panel><Panel title="Manual payment"><Field label="UPI ID" placeholder="organizer@upi" value={upi} onChange={setUpi} /><div className="mt-4"><Field label="WhatsApp" placeholder="+91..." value={whatsapp} onChange={setWhatsapp} /></div></Panel><button disabled={saving} type="submit" className="flex h-12 w-full items-center justify-center gap-2 rounded-[12px] bg-[#18181c] text-[12px] font-black text-white disabled:opacity-60 dark:bg-[#f6c945] dark:text-[#15151a]">{saving ? "Saving…" : editingId ? "Save changes" : "Save event draft"}<ArrowRight size={15} /></button></aside></form></main><Footer /></>;
}

'''
text = text[:start] + replacement + text[end:]
path.write_text(text)
